import { test, expect } from '@playwright/test';

test.describe('Dynamic Content Updates Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should announce dynamic content updates to screen readers', async ({ page }) => {
    await page.click(getByRole('button', { name: /load content/i }));
    const dynamicContent = await page.getByRole('alert');

    await expect(dynamicContent).toBeVisible();
    await expect(dynamicContent).toHaveText(/new content loaded/i);
  });

  test('should not announce static content to screen readers', async ({ page }) => {
    const staticContent = await page.getByText(/static content/i);

    await expect(staticContent).toBeVisible();
    await expect(staticContent).not.toHaveAttribute('aria-live', 'assertive');
  });
});
